#include<stack>
using namespace std;
​
int main() {
    vector<int> ans;
    int tmp;
    while (cin >> tmp) {
        ans.push_back(tmp); 
    }
​
    int n = ans.size();
    vector<int> stk(n,0);
    // 下一个要放入的位置
    int pos = 0;
    for (int i = 0; i < n; i++) {
        long sum = ans[i];
        long tmp = sum;

        // 递归进行压栈判断
        while (pos > 0 && tmp >=0) {
            int j = pos - 1;
            for (; j >=0; j--) {
                tmp -= stk[j];
                if (tmp <= 0) {
                    break;
                }
            }
            // 满足条件，更新元素
            if (tmp == 0) {
                sum = 2 * sum;
                pos = j;
                tmp = sum;
            } else {
                break;
            }
        }
​
        stk[pos++] = sum;
    }

    for (int i = pos -1; i >=0;i--) {
        cout << stk[i] << " ";
    }
    return 0;
}

