/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require('readline');
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
function main() {
    let ans = [];

    // 读取输入数据
    rl.on('line', (input) => {
        if (input.trim() === '') {
            // 结束输入
            rl.close();
        } else {
            // 将输入的字符串按空格分割，并转换为整数
            ans.push(...input.split(' ').map(Number));
        }
    });
​
    rl.on('close', () => {
        let n = ans.length;
        let stk = new Array(n).fill(0);
        let pos = 0;
​
        for (let i = 0; i < n; i++) {
            let sum = ans[i];
            let tmp = sum;
​
            // 递归进行压栈判断
            while (pos > 0 && tmp >= 0) {
                let j = pos - 1;
                while (j >= 0) {
                    tmp -= stk[j];
                    if (tmp <= 0) {
                        break;
                    }
                    j--;
                }
​
                // 满足条件，更新元素
                if (tmp === 0) {
                    sum = 2 * sum;
                    pos = j;
                    tmp = sum;
                } else {
                    break;
                }
            }
​
            stk[pos] = sum;
            pos++;
        }
​
        // 输出栈中的元素
         console.log(stk.slice(0, pos).reverse().join(' '));
    });
}
​
main();
