package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    // 从标准输入读取数据
    scanner := bufio.NewScanner(os.Stdin)
​
    var ans []int
    if scanner.Scan() {
        line := scanner.Text()
        inputs := strings.Fields(line)
        for _, val := range inputs {
            num, err := strconv.Atoi(val)
            if err == nil {
                ans = append(ans, num)
            }
        }
    }
​
    n := len(ans)
    stk := make([]int, n)
    pos := 0 // 下一个要放入的位置
​
    for i := 0; i < n; i++ {
        sum := ans[i]
        tmp := sum
​
        // 递归进行压栈判断
        for pos > 0 && tmp >= 0 {
            j := pos - 1
            for j >= 0 {
                tmp -= stk[j]
                if tmp <= 0 {
                    break
                }
                j--
            }
​
            // 满足条件，更新元素
            if tmp == 0 {
                sum = 2 * sum
                pos = j
                tmp = sum
            } else {
                break
            }
        }
​
        stk[pos] = sum
        pos++
    }
​
    // 输出结果
    for i := pos - 1; i >= 0; i-- {
        fmt.Print(stk[i], " ")
    }
}
